import { OWNER_SUPPLIED, type EventTable } from "./types";

/** Таблица из документа, переданного владельцем. Строки описательные: движок бросает
 *  и показывает выпавшее, применяют его за столом. */
export const TABLES: readonly EventTable[] = [
  {
    id: "adventure-hooks",
    name: "Идеи и зацепки приключений",
    group: "Приключения и зацепки",
    die: 149,
    source: OWNER_SUPPLIED,
    sourceNote:
      "Из 230 пунктов исходника снят 81: 72 опирались на Забытые Королевства, 9 — на другие сеттинги и изданные приключения. Оставшиеся 149 перенумерованы подряд, чтобы кость закрывалась без дыр.",
    rows: [
      { from: 1, to: 1, text: "Персонажам нужна информация о чем-то ОЧЕНЬ редком. Такая есть только в спецовых книгах в самых крутых библиотеках крупных городов. Персы, прибыв в город, находят в библиотеке в соотв отделе непонятную ситуацию: смотритель этого отдела был дэв, довольно-таки высокомерный маг. Он бросил вызов группе других магов, чтобы доказать свою силу, положил многих, но был убит и переродился в ракшасу. Теперь информация о нужной книге есть только у какого-то ракшаса. Для начала узнаем имя; потом, разыскиваем его - выясняем что ракшаса - заправила в крупном преступном синдикате. Находим его, он предлагает сделку: инфа в обмен на услугу. \"Услуга\" выбирается мастером, я бы предложил притащить редкую штуковину из руин... Соотв получаем требуемый кусок инфы о книге, и находим ее в библиотеке." },
      { from: 2, to: 2, text: "Треант-хранитель древнего леса пропал и теперь каста варденов ищет виновных" },
      { from: 3, to: 3, text: "После землетрясения открылись шахты, из которых полезли спелл-плаг-мутанты и теперь терроризируют дороги, а местные поговаривают, что они похищают народ и бросают их в свои котлы" },
      { from: 4, to: 4, text: "Злой орк дерётся с каждым в местной таверне на дубинах мягких (бамбалыгах) на деньги и никто его не может победить, ведь он - местный офицер" },
      { from: 5, to: 5, text: "Два городских офицера соревнуются в бардовском исполнении, что уже всех вокруг достало" },
      { from: 6, to: 6, text: "Кто-то подкармливает около города волков и лесные хищники просто уже стаями ходят в окрестностях" },
      { from: 7, to: 7, text: "В полях стали пропадать местные, а кто-то из выживших говорит, что за ними пришли живые корни" },
      { from: 8, to: 8, text: "В таверне поселился странный маг, поставивший магическую дверь и что-то делающий внутри, а каждую ночь их его комнаты видна радуга" },
      { from: 9, to: 9, text: "Пираты похищают детей состоятельных горожан и прячут их куда-то" },
      { from: 10, to: 10, text: "Найдены пещеры с довольно редким ресурсом, но там обосновался отряд дуэргаров, хотя для них это место слишком близко к поверхность" },
      { from: 11, to: 11, text: "В ближайшем городе значимая гильдия вдруг начала набор приключенцев в массовом порядке, но почему-то никто туда не торопится" },
      { from: 12, to: 12, text: "В городе несчастье. За последний период порядка 80% рождений окончились мертворождением. Исключение составляет только местная диаспора дварфов." },
      { from: 13, to: 13, text: "Местный крупный скотовладелец терпит убытки от внезапно активизировавшихся воргов и волков. Его стадо постоянно сокращается. В процессе выполнения \"расследования\" может всплыть информация о том, что стадо скотовладельца застраховано." },
      { from: 14, to: 14, text: "Группа приключенцев ходила в Зачарованный Лес. Вернулись не все, да и те - полные психи, несущие, обычно, околесицу." },
      { from: 15, to: 15, text: "Один из местных охотников рассказывает в таверне о том, что видел как в нескольких милях от городка в лесу разбился летающий корабль. Выживших было трое - странные существа,которых он прежде не встречал. Они волокли в лес какое-то неизвестное металлическое устройство, и не смотря на ранения, очень торопились. Через некоторое время на место крушения прибыла команда городских магов, но вот уже как 3 дня от них ничего не слышно. Город готовит поисковую партию." },
      { from: 16, to: 16, text: "Один полусумашедший дженази маг утверждает, что узнал страшную тайну Богов, и что ему обязательно необходимо все рассказать \"Совету Магов\". Большинство над ним только посмеивались, пока он не пропал, а в город не прибыла странная группа людей, состоящая из клериков различных богов и воинов в сверкающих доспехах, наводящих о нем справки и усиленно занятая его поисками." },
      { from: 17, to: 17, text: "В городе пропадают люди, а через некоторое время и вовсе начинает свирепствовать неизлечимая чума, все наводки - ведут к последнему пропавшему - нелюдимому орку- кузнецу. В кузнице которого можно найти книгу, изучив которую, можно составить ритуал древнего проклятья. Под домом кузнеца обнаруживается проход в пещеры, затронутые Шэдоуфэлл. А в стене кузницы - листочек, на котором нарисована схема изготовления кулона-сердечка." },
      { from: 18, to: 18, text: "Портовый город находится в упадке из-за преступности. По ночам нельзя спокойно выйти на улицу. Героям поручается убить главаря самой мощной банды, но спустя неделю после своей смерти - этот главарь возвращается, собирает банду и начинает преследовать игроков." },
      { from: 19, to: 19, text: "Зайдя в пещеру и убив живущего там великана, приключенцы натыкаются на полу- мёртвого дроу (один из игроков) без памяти, которого великан собирался скормить своему питомцу. Они спасают дроу, но через некоторое время на него начинают охотится ракшасса. При осмотре дроу на аркану - обнаруживается, что на нём лежит какое-то мощное заклинание, действующее на память." },
      { from: 20, to: 20, text: "В пещере молодого дракона группа приключенцев находит странную адамантиновую пластину с рунами, от которой прямо таки \"несёт\" магией. В городе они встречают дворфа-артифайсера, весьма заинтересованного в получении этой пластины. Если они продают её - то он подсовывает им Fool's Gold (Fool's Platina ;) ), если не продают - начинает их преследовать. Никто из местных магов не справляется с переводом рун. Артифайсер оказывается одним из ученых, исследующих магическую чуму (Spell plague)." },
      { from: 21, to: 21, text: "Игроки являются членами ордена, расследующего магические преступления. Они узнают от предсказателей ордена, что мощный ритуал, произойдёт где-то на севере страны, рядом с одиноко стоящей деревушкой. Там они находят лишь небольшую группу сектантов, выполняющих ритуал призыва чего-то, но убив их они вызывают ошибку в связи телепортов, и случайно, в руинах оказывается последний член партии (в это же время его телепортировали на задание), рядом с собой он находит ритуальный нож. В деревне их радушно встречает староста, у которого игроки узнают, что о ноже может рассказать только колдунья-отшельница, живущая в горах. По пути игроки попадают в засаду бандитов, и их начинают преследовать демоны." },
      { from: 22, to: 22, text: "Игроки попадают в большой город. Пройдясь по городу и слегка потратив денег, они замечают, что город буквально \"прогнил\": проституция, воровство, коррупция пропитали его насквозь. Вскоре город сотрясает волна убийств влиятельных людей, вскоре игроки узнают что в этом замешан некий тайный орден." },
      { from: 23, to: 23, text: "Жители деревушки вдруг осознали, что не помнят последние три дня. Староста просит помощи у клириков и магов соседнего города, чтобы разобраться в том, что произошло за эти дни. Последнее сохранившееся воспоминание у одного из жителей - возвращаясь с мельницы домой, он повстречал странного человека, спросившего у него дорогу в деревню. Кожа его была крайне бледной и говорил он с акцентом." },
      { from: 24, to: 24, text: "За одну ночь в центре города, на площади, выросло гагантское дерево неизвестной породы. К вечеру на нем стали появляться красные плоды, похожие на нечто среднее между яблоками и бананами. Все, кто приближается к дереву на расстояние 10 футов чувствуют слабость." },
      { from: 25, to: 25, text: "Игроки попадают в деревню, в которой произошла напасть - на жителей деревни напала химера, которая раньше изредка питалась скотом, но в последнее время приноровилась нападать на местных жителей среди белого дня. В процессе расследования узнается, что все жертвы как-то связаны с особняком, находящимся неподалёку от деревни, хозяин которого недавно умер. Совсем скоро очередной \"целью\" становятся сами игроки..." },
      { from: 26, to: 26, text: "По дороге из села в город игроки встречают человека, который просит их помочь за небольшое возногрождение. На его село(которое находится в дне пути от основных дорг) нападают серые существа и забирают с собой жителей. В ходе разборок, жители села, для спасения своих жизней (их запугали) пытаются \"скормить\" существам игроков, всместо своих. (существа - гримлоки)" },
      { from: 27, to: 27, text: "Дочка купца похищенна одним из Баронов. Он просит ее вернуть." },
      { from: 28, to: 28, text: "Привидение на перекрестке дорог убивает (отрезает головы) всех кто там появляется. Привидение ищет свою голову, которую ему отрубили и забрал один из......" },
      { from: 29, to: 29, text: "Шахтеры наткнулись на \"огненных людей\" (азеры) которые \"сидят\" в пещере (своей пещере, а люди туде приперлись :) ) и убивают всех кто приблежается.....а там такая богатая золотая жила......." },
      { from: 30, to: 30, text: "Банда с полу-орком терраризирует гильдию купцов на дороге, пролегающей возле пустыни. Нападения происходят внезапно и так же внезапно банда исчезает. (Она обосновалась в гробнице Древних где нашла амулет который активирует Circle Of Teleportation находящийся возле дороги. Где раньше был один из храмов и второй телепорт в гробнице." },
      { from: 31, to: 31, text: "Израненных персонажей приютила семья простолюдинов в весьма большом селе (150- 200 домов), выходила их, и они понемногу начали помогать тем, кто их приютил. И вот однажды, за 2-3 дня до того, как приключенцы должны были уже уходить, случилось несчастье: пока кто-то с главой семьи помогал с товаром на ярмарке в соседнем селе, а кто-то из приключенцев работал в поле со старшими сыновьями (короче никого не было дома кроме малых и матери), на дом напали… вернувшись, приключенцы узнают, что одну из младших дочек похители, а точнее приватизировали, ведь герцог, которому принадлежат эти земли относиться к своим людям как к вещам, но самое страшное, что он порочен, ведь он похищает девушек. Семья безутешна." },
      { from: 32, to: 32, text: "После какого-то непыльного приключения, но прибыльного, партия (здесь конечно присутствует элемент «если») жестко ступила, когда, не зайдя в проходящем городе к меняле, в трактире расплатились золотом. Ночью на партию напали и надавали по рогам до отключки. Все ценности угнаны (оружие – если плохого качества – то оставлено у партии, если хорошо сделанное – украдено, если именное - сломано), если в партии есть женщины – изнасилованы. Месть, это такая штука…" },
      { from: 33, to: 33, text: "Приключенцы идут по улице и видят нападение на хорошо одетого человека. Они помогают ему и он нанимает партию в телохранители. Постепенно выясняется, что этот человек - член Городского Совета, который недавно продавил план ремонта городской канализации. Обитающая там община кобольдов (можно заменить на любых других монстров или даже мафию) этим весьма недовольна и предпринимает массу усилий, чтобы устранить Советника (все держится исключительно на нем и если он погибнет - ремонт прекратится). Далее предполагается пара хитрых покушений и поход в канализацию для \"зачистки\"." },
      { from: 34, to: 34, text: "Ищем чувака, который крайне редко появляется в городе, известно, где он жимвет, известен возраст и то, что он колдун, плюс постоянное место жительства (долина така-сякая), но не точный адрес." },
      { from: 35, to: 35, text: "Некий город, в котором пребывают ныне герои, построен на туловище дезактивированного каменного колосса, который за несколько столетий оброс домами, землей и жителями. Способ пробуждения этого существа знают лишь только самые древние эльфы, которых и так уже мало. И вот они начинают один за другим исчезать и появляться в зверски умерщвленном виде со следами насилия и пыток..." },
      { from: 36, to: 36, text: "Группа (большого льва, успевшая нажить себе много врагов) подряжаются на какое ни будь простое задание на большом расстоянии от крупных населенных пунктов. В процессе выполнения, каждый раз, как группа засыпает (сон их смаривает автоматически вместе) они оказываются в каком-то подземелье в одиночной камере, из которой они начинают дружно искать выход. Подземелье насквозь пропитано магией, которая заставляет игроков поверить, что это все сон. На самом деле их текущее путешествие является навеянным сном, а вот действия, происходящие во сне, являются наоборот реальными." },
      { from: 37, to: 37, text: "Вторая вспышка магической чумы. Двое приключенцев, путешествующих по зоне в поисках карты, позволяющей постичь \"как можно проникнуть в сердце зоны (известно, что сердцем вспышки стал мощный маг. артефакт) оказываются в пещере без памяти о последних событиях. И вскоре находят ту самую карту, но она вся заляпана и практически непригодна. Вместе с картой они находят еще 3-х полу- мертвых созданий, которые неизвестно сколько лежали в этой пещере вокруг хозяина карты... Как только приключенцы пытаются взять эту карту её хозяин оживает, но не как ревенант, а как мощный зомби... Пройти до магического артефакта или выбраться из зоны? Довериться наполовину-мёртвым существам? Что и зачем оживило давно погибших приключенцев? Как давно они лежат здесь? Какие дары может подарить отважным авантюристам зона магической чумы?" },
      { from: 38, to: 38, text: "Трое исследователей из цивилизованного мира летят на орнитоптере через дикие земли племён, чтобы исследовать пещеры богатые минералами и под влиянием неведанной им магии терпят крушение в сердце диких земель. Звуки их падения к ним на встречу выходят местные жители. Среди которых оказывается несколько довольно талантливых существ, с радостью согласившихся им помочь. Спустя некоторое время приключенцы узнают, что дикие земли погружены в захватническую войну, и мощная армия уже взяла верх над основными племенами... И совсем скоро разведчики этой армии тоже выходят на след упавшего орнитоптера. Пробиваться вперед к своей цели? Помочь местным жителям спасти свои племена? Или возвращаться в столицу дабы разбудить его войной? Кто и как сбил орнитоптер? Как привыкшим к трехразовому питанию цивилизованным жителям придется жить в диких степях? Долг или выгода?" },
      { from: 39, to: 39, text: "Большим островом заправляет некая баронесса (столько же таинственная, сколько нелюдимая), влиятельная, но до упёртости нейтральная. Её уважают, но втихаря ненавидят или хотят переманить её капиталы на свою сторону. Недавно объявила, что проводит бал всех балов, который будет длиться неделю и выслала приглашения самым влиятельным людям из высшего общества. По слухам на балу она отдаст своё величайшее сокровище, но сети заговоров заказных убийств ещё до начала бала заставляет задуматься, а не ради ли смуты она устраивает это???" },
      { from: 40, to: 40, text: "Приключенцы, путешествуя по огромным тропическим лесам, поднимаются в гору вдоль широкой реки. Река заканчивается гигантским водопадом. Почти у самого обрыва по середине реки расположился старый особняк, мост к которому, недавно был разрушен (точнее взорван). Видно, что замок находится в хорошим состоянии. Ворота в замок естественно закрыты, но попасть в него возможно. Внутри замка отчетливо видны результаты сражения, присутствуют следы крови, сломанных мечей, щитов и т.п., но нет ни одного трупа. Если пати продолжает осмотр замка, то при исследовании одной из комнат слышат металлический скрежет. Ворвавшись в комнату, они замечают странный маленький силуэт, который, едва завидев их, быстро шмыгнул в одну из дыр в стене и скрылся. Единственное, что замечают приключенцы это красные глаза и противный скрежет металла..." },
      { from: 41, to: 41, text: "Персонажи остановились в городке/деревне. Вскоре до них доходят слухи о том, что по ночам на коровники нападает какой-то зверь. При вылазке в лес партия встречает лесника, который предостерегает их от охоты на зверя. Если партия устраивает засаду в коровнике, то ночью туда приходит существо, оказавшееся вервольфом. Если бой складывается не в его пользу, оборотень драпает. Удачная погоня приводит отряд в логово твари - пещеру, в которой также живут волки (или Dire wolves). Убитый оборотень трансформируется обратно в человека, который оказывается... лесником." },
      { from: 42, to: 42, text: "Призрак древнего богача-мудреца сторожит собственную гробницу. Он обожает игру в загадки. Тот, кто его обыграет (отгадает все загадки мудреца или задаст такую, какую тот не отгадает), получит от него золото и маг. предмет в качестве награды и поощрения. А кто не обыграет - будет телепортирован в другую часть гробницы, и до выхода на свет придется добираться через несколько комнат с ловушками." },
      { from: 43, to: 43, text: "Из городского зоопарка \\ зверинца графа \\ заезжего цирка в город сбежал тролль \\ любое человекообразное существо с зачатками интеллекта." },
      { from: 44, to: 44, text: "Сплетаются несколько событий, вроде бы не связанных между собой: Начинает буйствовать Святая Инквизиция - фанатики, еретики, костры и все подобное; Повсюду поднимается нежить, происходят ужасные вещи (гибнут люди, животные становятся дикими и нападают на людей... +еще на усмотрение ДМа); Вторжение с другого плана. Вся соль в правде. Один злобный бог свел с ума бога доброго (и свихнулись его святые слуги). Темный бог начинает экспансию в мир (со всей вытекающей нежитью).Видя, что мир рвут на части, все это время выжидавшие планарники стремятся ворваться в мир." },
      { from: 45, to: 45, text: "Город, в котором находятся приключенцы, проклят сожженным на костре колдуном. Колдун вызывает к помощи Темные силы, которые обрушивают на город проклятия: Чуму; Войну с любым другим городом/напавшими орками и т.д. (следствие видение, приснившегося шаману); Землетрясение; Разупокоение мертвых (следствие заклятия=))" },
      { from: 46, to: 46, text: "Местная деревня не знает к кому обратиться - деревья в лесу каждой ночью буквально смыкают рощу вокруг и небо над головой. Местный староста едва не на коленях просит помощи у приключенцев. Что скрывают библиотекарь и священник? Куда исчез друид сразу после того, как волки загрызли местного охотника? Замешана ли молодая девушка-малефик?" },
      { from: 47, to: 47, text: "Чудаковатый маг (или аристократ) непись. Владеет зверинцем для экспериментов/увеселения. Он просит партию героев помочь ему достать для коллекции несколько редких животных (ключевое условие - живыми), некоторые из которых довольно опасны сами по себе. Мотивация - как обычно - бешеные деньги в награду или шмот. В процессе выполнения этого квеста, если бегать и охотиться надоест, можно разыграть какие-нибудь события, типа побега, поджога и пр. неприятностей." },
      { from: 48, to: 48, text: "Аристократ предлагает ПиСи никого не убивать и не ловить, а наоборот: защитить себя/жену/отрока/ещё кого от асассинов на время переговоров с важной шишкой соседнего государства, например. Асассин судя по Доверенным Источникам (тм) должен быть довольно сильный (так чтобы партии в открытую даже пришлось с ним повозиться)." },
      { from: 49, to: 49, text: "Один из местных стражей города мечтает организовать свою гильдию воров, а потому чужими руками мечтает обокрасть тайник городского скупердяя. Вот только хватит ли ему самому духу всё это организовать и можно и нужно ли его остановить." },
      { from: 50, to: 50, text: "Герои проездом оказываются в неком свободном городе, где глава местной торговой гильдии просит их об одолжении: помочь защитить его караван, в скором времени отправляющийся из этого города в гномские земли. Обычно по пути следования караваны подвергаются диверсиям со стороны эльфийских партизан, потому что часть маршрута проходит через их владения, рэкету со стороны личной гвардии самопровозглашенного короля соседнего региона и засадам бандитов под предводительством некоего блэкгарда уже вблизи гор. Через несколько часов после этого разговора к героям поступает предложение напасть на данный караван, переданное представителем одной из вышеозначенных фракций. Соответственно, персонажам предстоит выбор, грабить корован или не грабить..." },
      { from: 51, to: 51, text: "Партия в ходе путешествий натыкается на крошечную лесную деревню. Просит там еды и ночлега. Их устраивают в ратуше (амбаре, хлеве) ночью на них совершается нападение, их связывают, отбирают оружие и ведут в лес. Оказывается, все жители деревни ликантропы и собираются устроить Кровавую Охоту, или как ее там, в честь Малара. Их развязывают и дают минут 10 форы. Затем начинается погоня. Задача игроков - выжить. Как вариант можно добавить интриги и разногласия в руководстве оборотней, NPC охотника на оборотней, других жертв и все такое." },
      { from: 52, to: 52, text: "Персонажам необходимо пробиться через Завесу - заклятие, не позволяющее перемещаться между планами. Они обращаются за помощью к планарному магу, который проводит ритуал, частью которого является заточение персонажей в Пирамиду Теней. Лишь выбравшись оттуда и разрушив ее, Пирамида разорвет на некоторое время Завесу." },
      { from: 53, to: 53, text: "На партийного (или крайне важного как персонажа) иллитида начинает охоту рраккама. Это отряд гитзераев для уничтожения минд флаеров. Все начинается с того, что после телепортации иллитид исчезает. Поиски начинаются!" },
      { from: 54, to: 54, text: "Из местной тюрьмы сбегают \"особо опасные\" преступники. В городе сразу же проходит страшный слух - теперь каждое ваше слово будет подслушано, а каждое действие замечены. Предположения о преступниках одно хуже другого - начиная от Нечисти, заканчивая вампирами. Партии поручают с этим разобраться. Через некоторое время за героями начинается слежка... глазами партии. Доппельгангеры- преступники уже внутри партии и стараются ее поссорить." },
      { from: 55, to: 55, text: "Начинающую партию героев собирает герцог. Персонажи уже были знакомы три года назад между собой на войне и знали одного генерала. Вот именно этого генерала и просят найти. Известно, что этот благородный человек связался со злом. Чем это может окончиться решит сама партия, учитывая, что у каждого из них свои виды на генерала." },
      { from: 56, to: 56, text: "Герои прибывают в город, где секта, ментально зомбированная и подчинённая иллитидам заманивает в свои ряды новичков и передаёт их в рабство под землю своим хозяевам." },
      { from: 57, to: 57, text: "Герои проезжают территорию одного государства, во всех крупных городах которого есть арены, где каждый день проводятся кровавые бои, преимущественно между гладиаторами и естественно с летальными исходами. Подобные зрелища создают у горожан определенный менталитет, и, как возможно узнают впоследствии персонажи, желающих пополнить ряды гладиаторов всегда полно. Как они в дальнейшем узнают, суть в том, что гладиаторам покровительствует один из местных богов смерти/загробия, а его благословение привносит в статус гладиатора определенные льготы и права. Более глубокий анализ ситуации позволяет выяснить, что на самом деле бои на аренах являются замысловатым ритуалом жертвоприношений тому самому богу, а трупы и расчлененку не хоронят и не кремируют. Останки павших подлежат трансформации в неупокоенных различных форм и возможностей, пополняя собой армию живых мертвецов, в катакомбах ждущих своего часа выйти под руководством могущественных некромантов в бой против другого государства." },
      { from: 58, to: 58, text: "Группа приключенцев привозит ценную вещь в особняк знатного господина. Там идет небольшая тусовка «для своих», даже слуг минимум. Время позднее и приключенцев размещают на ночевку вне здания. Но спустя некоторые время хозяин дома зовет их. Произошло убийство, убит один из гостей и сделал это кто-то из своих. Желая непредвзятости хозяин дома разрешает команде провести расследование (можно как- то мотивировать это, например часть команды ранее служила в городской страже или уже занималась подобными вещами и имеет хорошие отзывы). В самом начале расследования происходит второе убийство, погибает супруг/супруга первой жертвы. Сложность расследования в том, что убийц двое, и они абсолютно не связаны с друг другом. Одну жертву убивают по политическим мотивам, а вторую исходя из личных отношений. Кроме того оказывается что у хозяина дома, который не замешан ни в одном преступлении, есть внушительный «скелет в шкафу». Ну и напоследок, поскольку все гости люди знатные, то применять к ним магию без их прямого согласия нельзя, а аристократическая гордость и осторожность не позволяют им на это согласиться. (приключение рассчитано больше на работу головой, общение с персонажами и знание элементарных основ криминалистики и следственного дела.)" },
      { from: 59, to: 59, text: "Цех мясников одного города в качестве подмастерьев принимает как обыкновенных, так и способных к магии кандидатов. В чем заключается специфика выбора таких критериев - неясно не посвященным. Однако, способные к магии мясники и их подмастерья живут гораздо богаче своих менее талантливых коллег и секреты ремесла не стремятся раскрывать посторонним. Откуда у цеха столько денег на содержание магов? Чем там занимаются мясники, может воскрешают нежить или строят плотских големов? Или работают на оборону?" },
      { from: 60, to: 60, text: "В лесном массиве, в котором, естественно, живут разные эльфы, гномики, и проходит несколько торговых путей, начинаются акты разбоя, вайпа мирных жителей и нападения на караваны с признаками, характерными для драконов. Поначалу, всю вину сваливают на местную диаспору зеленых драконов, которые уже как лет сто подобными вещами не занимались и жили относительно мирно. Однако, как впоследствии узнают персонажи игроков, налеты совершают... молодые красные драконы, которых по идее здесь быть не должно. Непосредственное общение уже с представителем красных обнародует новую информацию: оказывается, их выводок раньше жил в подземных пещерах под этим регионом, но был едва ли не буквально выгнан племенем... кобольдов (sic!). Фактически, братьями меньшими. Красные же посчитают целесообразным заставить игроков плясать под свою дудку и предложат/настоятельно порекомендуют им разобраться с кобольдами в любой форме. Из доступной информации: лидер кобольдов ненавидит полноценных драконов и, по- видимому, стремится их уничтожить. Его племя за несколько десятилетий сменило три места жительства, и далеко не всем драконам, обитавшим там ранее, повезло хотя бы свалить." },
      { from: 61, to: 61, text: "Через пять часов состоится разводка: игроки доверились оракулу-который должен прислать к ним почтенного старца-старец будет излагать задания на пути постижения тайных знаний,\"я уста его,я сущность мыслей его..Его голос звучит у меня в голове..думаю,что к концу партии выяснится,что старик не оракул вовсе-а просто сумасшедший (шизофреник,параноик,маньяк-как уж на дайсах ляжет=)" },
      { from: 62, to: 62, text: "Могучего некроманта, наконец, изловили и через два дня состоится казнь в центре среднего города. Некромант вину признал, чтобы уберечься от пыток, от убеждений отрёкся.. Стража утаскивает в тюрьму под руки сельского седого священника, который, вырываясь, кричит, что \"его нельзя казнить, Бог отвернётся от нас\". Слышат разговор двух магов, которые разговаривают про заклинание \"Пат\"-делаемое в момент смерти,магия крови-учёные разговоры про жертвоприношения и тп. Игроки по сути понимают, что почему то некромант желает собственной казни(чтобы превратиться в лича он должен умереть насильственно),его казнь будет последней из двадцати..и если он сумеет собрать мощь от предыдущих-будет большая беда. Но сильных магов в городе нет-а переубедить церковников,после уничтожения двух соборов Н-м,будет ой как не просто(обвинение в ереси,и тп вплоть до наёмных убийц) +Игрокам будут мешать сектанты в чёрных балахонах(Гулли и неживые не мёртвые)" },
      { from: 63, to: 63, text: "Крупный религиозный праздник, местные жители наряжаются, маскарад длится несколько дней, а на главной площади человек, одетый в нечисть, убивает важную персону. Никто не знает, кто это был, свидетелей куча, паника, расследование, стража из столицы. У меня ВИПа убил настоящий демон, вызванный магом по заказу завистника." },
      { from: 64, to: 64, text: "Около города находят лапу неизвестного существа, предположительно, насекомоподобного. Через несколько дней из ближайшей деревни пропадают два человека, возле леса обнаружены следы. Незадолго до этого из леса начинает убегать зверьё." },
      { from: 65, to: 65, text: "Персонажи поступают в распоряжение капитана стражи в городе, который находится на осадном положении. Капитан разыскивает беглого преступника-мага, который скрывается в окрестностях города и его катакомбах. Персонажам поручено отправится в катакомбы и отыскать одного из сообщников мага. Катакомбы опасны и непредсказуемы, но не в этом главная загвоздка. Сообщника необходимо схватить, но он может устроить встречу с самим магом. И по итогу персонажи могут начать работать либо с преступником, либо продолжать выполнять поручения капитана. И последняя схватка произойдет в тот момент, когда вражеские войска начнут штурм города..." },
      { from: 66, to: 66, text: "Скудно одетый мужчина говорит его обокрали, просит пойти навалять бандитам, он обещает показать где они, приводит прямо в лагерь бандитов, оказывается что он сам один из них и они хотят гоп-стопнуть героев." },
      { from: 67, to: 67, text: "Чудаковатый волшебник в качестве своей лаборатории обустраивает подземный комплекс. Он просит партию самых примелькавшихся в регионе приключенцев пройти несколько тестов систем безопасности и после теоретических выкладок просит непосредственно оценить некоторые из установок. Вручив героям магическое защитное снаряжение, он отмечает на карте подземелий маршрут и отправляет вперед. Впоследствии оказывается, что снаряжение разряжено/проклято, карта не соответствует действительности, а сам колдун готовится к сознательной некротизации." },
      { from: 68, to: 68, text: "Статуя, стоявшая на городской площади последние полторы тысячи лет, оказывается окаменевшим паладином. За это время город пережил пару майданов с обязательным сносом памятников, несколько пожаров и церковных расколов, что негативно сказалось на древнем воине: он потерял руку вместе с храмовой реликвией и священный щит, воссоздать которые так или иначе — отдельная задача. Медуза, обратившая его взвод в камень, давно сдохла, а на месте их последней битвы вырос новый город. Однако у паладина осталась одно незавершенное дело — узнать судьбу своих павших товарищей и найти их статуи, если таковые сохранились. Всего их пять." },
      { from: 69, to: 69, text: "Порталы, позволяющие мгновенно переноситься между двумя зонами, установленные между двумя городами, начали сбоить. Когда пропадали одинокие путники, власть не сильно беспокоилась. Но когда при телепортации потеряли очень большой груз зеркального камня, засуетилась и подключила к проблеме всех доступных ученых. Персонажам, нанятым жречеством Эона, предстоит отправиться в портал, найти и доставить груз. Действительно, порталы выводят \"куда-то не туда\", однако впоследствии оказывается, что проблема не в месте, а во времени — ожидаемое время выхода сдвинуто на два миллиона лет, причем не понятно, в прошое или будущее." },
      { from: 70, to: 70, text: "Одного из тех самых святых воинов недавно видели в \"Пожилом Единороге\", он искал утешения на дне бутылки. Поговаривают, что он ездил к дварфам насчет вступления в Инквизицию. И теперь всё свободное время парень пьёт за барной стойкой, а на его голове добавилось седых волос." },
      { from: 71, to: 71, text: "Не пей красный эль в таверне \"Веселая Черепаха\". Старая дамочка по имени Миллер как-то выпила и однажды ночью превратилась… в злобного хорька! Нет, я не пьян и говорю серьёзно!" },
      { from: 72, to: 72, text: "Один худосочный парень прибыл в город два дня назад. Он зашёл в товарную лавку и скупил все съедобные припасы. Он говорит, что еда ему понадобится только, если что- то пойдёт не так. Я ничего не хочу сказать, но выглядит это подозрительно." },
      { from: 73, to: 73, text: "Эй, а вы знаете, что Западное кладбище построено на старой деревне? Да, они просто снесли все ее остатки и возвели кладбище. Звучит жутковато." },
      { from: 74, to: 74, text: "Не хороните слуг Бога Смерти. Говорят, что некоторые из них знают что-то вроде ритуала, чтобы после смерти восставать нежитью типа зомби, но с полным набором воспоминаний. Если один из вас умер рядом с вами - подумайте об огне. Хорошенько подумайте." },
      { from: 75, to: 75, text: "Не давайте денег этому полуорку Ургрону! Он говорит, что ему нужны деньги на какую-то экзотическую трубку или что-то в этом духе. Проблема в том, что полгода назад на его же месте сидел другой полуорк. И с тех пор, как он собрал деньги на эту свою хреновину, его больше никто никогда не видел." },
      { from: 76, to: 76, text: "Держитесь подальше от восточной дороги ночью. Поговаривают, что тень дварфа бродит по ней и ищет стражника, который прирезал его на входе! Так что держите себя в руках и выезжайте засветло." },
      { from: 77, to: 77, text: "Хоббит по имени Мрак ищет деньги для своей экспедиции. Тысячу золотых монет. Говорит, что собирается охотиться на дракона. Правда, когда кто-то в последний раз давал ему денег на экспедицию, то этот кто-то остался без гроша." },
      { from: 78, to: 78, text: "Мо умер от удара молнией год назад. Настоящая трагедия! Вот только он вернулся через неделю, весь с блаженной улыбкой на лице и о себе упоминает только в третьем лице. Называет себя Вестником Бога Порядка. Его мать считает, что вернуть бедняге прежнее состояние можно только вновь с помощью удара молнии." },
      { from: 79, to: 79, text: "Эти долбаные рисунки повсюду. Последние несколько недель кто-то постоянно рисует на стенах домов и в подвалах этот ужасный череп козла. Мы пытались оттереть краску, но её очень трудно смыть." },
      { from: 80, to: 80, text: "Мы никак не дождемся караван с поставками, который должен был прибыть ещё неделю назад. Я слышал, его охраняют два минотавра. Семеро сохрани, что могло случиться с караваном, который охраняют минотавры?!" },
      { from: 81, to: 81, text: "Вы когда-нибудь слышали об эльфийском барде в фиолетовом одеянии? Имя еще непроизносимое, как-то на -эль. Так вот, мне говорили, что он умер два года назад в результате несчастного случая. И затем из ниоткуда он вновь объявился в нашем городе буквально на днях. И знаете, он довольно хорошо выглядит для того. кто должен быть мёртв." },
      { from: 82, to: 82, text: "Крупный феодал желает знать о своих владениях больше и призывает героев для выполнения ответственного квеста: провести перепись населения в определенном районе королевства. Нужно проехать там, посчитать жителей в деревнях всех рас, их возраст тоже, в удаленных крепостях на границе с другим феодалом и в крупном городе тоже надо посчитать жителей. Феодал обещает щедрое вознаграджение и предоставляет грамоту, по которой игроки на время поездки приравниваются к членам его семьи. Зато он дает сроки (тут мастеру виднее, какую площадь надо объехать и к какому событию приурочить завершение переписи), поэтому все проблемы должны быть решены максимально быстро - бандиты на дорогах, распутица, мятежники, нападение дракона, бюрократические препоны и все такое." },
      { from: 83, to: 83, text: "По неизвестной причине солдаты правительства ходят по городам и выгоняют из них всех *вставьте расу*. Дальше может быть 3 варианта: - Предосторожность. Началась война с королевством *вставьте расу*. Дабы предотвратить шпионаж, всех *вставьте расу* высылают за границу. - Тирания. Жена короля изменила ему с *вставьте расу*, он в бешенстве начал мстить. - Незаконная деятельность. Король сам ничего не знает, а это нацисты, прикрывающиеся приказами." },
      { from: 84, to: 84, text: "События происходят на границе земель маркиза, барона и эльфийских лесов, проходящей по реке. Маркиз воюет с троллями на своей стороне реки и пытается на их землях основать рудники в горах. Барон притесняет эльфов на своей стороне и оспаривает право маркиза на его земли. Главгады: тайный культ некромантов в горах откопал руины древней цивилизации с порталом, и культисты пытаются его перенастроить для вызова демонов. Поэтому соседи в виде рудокопов маркиза или слишком умных эльфов им не нужны. Культисты в сговоре с троллями и бароном." },
      { from: 85, to: 85, text: "Героев нанимает в сопровождение каравана дворф в необычном наряде – на руке татуировка шестеренки, а украшениями являются золотые части различных механизмов. На привале, в явном подпитии, он рассказывает о странном, но не менее грандиозном городе Шестерни. На них совершает нападение, с использованием неизвестной магии, отряд из представителей различных рас, чьим гербом является сломанная шестеренка. Умирающий дворф передает кулон с камнем героям и просит вернуть его в город за вознаграждение - «сколько золота вы сможете унести в руках». В ходе приключения герои столкнутся с городом Шестерни, его жителями и порядком, узнают его появление и предназначение, мотивы и личность правителя города, посетят Море Павших Звезд, исследуют забытое богами герцогство, попробуют себя в качестве ловцов пиратов…" },
      { from: 86, to: 86, text: "Герои начинают приключение в виде наемников, которых нанимают охранять группу исследователей от различных напастей в древних руинах. После того, как они побродят по ним и поубивают мелкую шалупонь, обнаружится скрытый проход, куда все направятся. По случайности будет освобождено \"злостное зло\", которое покрошит всех и вся, но оставит в живых героев, чтобы сделать своей \"начальной армией\". С этого момента игроки ОБЯЗАНЫ ему подчиняться. Для начала малые разбои, затем более крупные мероприятия (еще вербовка жалких людишек и тп). По мере продвижения \"Главнюк\" откроет месторасположения различных точек, где предстоит пройти испытания, чтобы бустануть себя( 1 дандж= 1 человек). Злодеем движет жажда мести верховному совету магов, которые его заточили. Со временем они узнают о пробуждении(тем раньше, чем больше вы наглеете) и будут насылать карательные отряды(В последствии может дойти до крупномасштабной войнушки). Финал очевиден. Мстя завершена и тд(но эт скучно). В квесте возникнет несколько скрытых посланий, которые будучи раскрытыми приведут к \"секретной концовке\"." },
      { from: 87, to: 87, text: "Персонажа, в одиноком трактире на перепутье, встречают три девушки (хозяйка и две ее дочери официантки) в конце-концов, настойчивая любезность хозяйки приводит к ее просьбе взять младшую дочь замуж. Если не согласится - то начнется преследование от местных. Если согласится - то на свадьбе случится кровавая резня между двумя сектами древних богов." },
      { from: 88, to: 88, text: "Однажды, из самых глубин тёмных планов на план физический вышло исчадье, прихватив с собой могущественный артефакт. Он состоит из 8-ми камней вставленных в амулет. Исчадье объявило себя на весь мир, сказав что не собирается творить зло, а наоборот, набирает учеников для передачи им древних знаний магии. И вот, когда все 8 учеников были набраны исчадье, из камней в амулете сделал каждому по оружию (Клинки, кинжалы, волшебные палочки и т.д, на ваш выбор), но когда все ученики приняли свои подарки, исчадье подчинило их, с помощью амулета и с самыми могущественными магами пошло по городам и в итоге засело где-то после путешествий. Сумевшие кое-как оправиться от страшных потерь, города собрали свою армию, двинувшись на исчадье. По итогам боя восемь магов были убиты, исчадье с амулетом было изгнано на другой план и заточено там, а камни потеряли свою силу и оружие стало обычным. Города забрали их и начали хранить как трофеи. Но через десятки и сотни лет, какие-то камни всё же потерялись. И вот, теперь уже в наше время, герои натыкаются на один такой камень, узнают от могущественных магах о ещё 7-ми затерянных и амулете и когда собирают 8 камней, с их помощью могут открыть портал в тот план к исчадью, победить его и забрать амулет, который снова будет давать великую мощь, если вставить камни в амулет." },
      { from: 89, to: 89, text: "Бывший военначальник одного закрытого города, который с недавнего времени стал пускать иностранцев, объявил бунт и поднял армию нежити, чтобы бросить ее на «предателей», пустивших чужаков и на самих иностранцев." },
      { from: 90, to: 90, text: "Вампиры терроризируют торговцев в одном из городов. Оказывается, верхушка одной из организаций воров сделала себя вампирами для усиления своего влияния и большей наживы. Секретный лидер организации – мощный волшебник- вампир, поддерживаемый слугами-вампирами, способны ударить в городе где угодно. Рядовые члены организации не осмеливаются возражать, и народу города тяжело выступать против мощной и распространяющейся гильдии без страха вызвать кровопускание ужасных размеров." },
      { from: 91, to: 91, text: "Торговец из Анкапура утверждает, что нашел таинственные магические предметы, позволяющие их обладателю создать множество копий своего тела и свободно перемещать свой интеллект от одного к другому. Он предлагает их к продаже любому заинтересованному человеку за огромные деньги и пережил к настоящему времени три попытки убийства, в каждой из которых убивали одно из его запасных тел. Говорят, что его предметы могут быть легендарным Ожерельем Трингала, о котором говорят, что создание слишком большого количества тел может привести обладателя к безумию – одно из тел должно носить Ожерелье всегда, и урон, нанесённый одному телу, ослабляет все остальные." },
      { from: 92, to: 92, text: "Под одним из городов находятся руины древнего дварфского королевства с городами и обширными туннелями. Там наверняка есть сокровища, но и древние дварфские ловушки. Возможно и не только ловушки…" },
      { from: 93, to: 93, text: "Когда герои сражаются, неожиданная помощь приходит от Матрама Дерухеда – золотого дварфа – воина-волшебника верхом на гиппогрифе. Матрам выслеживает убийц своего брата-близнеца. В любом развитии сюжета, преступники окажутся старыми врагами игроков, убившие брата Матарма ради золота и драгоценных камней, которые он носил в своих волосах и бороде. Если игроки игнорируют Матарма, то позже они находят его убитым теми же злодеями, что убили и его брата. Возможно сделать так, что дварф на самом деле бежит от своего собственного народа по каким-то причинам." },
      { from: 94, to: 94, text: "Банда дварфов-скелетов при полных боевых регалиях идет через туннели, вырезая любых нападающих на них, кроме дварфов. Их мертвые противники теряют плоть и присоединяются в виде скелетов к этому маршу. Эта нежить не реагирует на священнические силы изгнания и они избегают дварфских поселений. Что является их целью? Возвращение важного для дварфов места? Убийство мощного противника, типа глубинного дракона? Или что-то еще?" },
      { from: 95, to: 95, text: "Есть огромное количество порталов из Подземья на поверхность земли. Ими могут воспользоваться дроу, дуэргары, куо-тоа и другие для погрома, поиска рабов или ради прибыли. Если у такой группы нет возможности быстро вернуться домой, они могут переждать дневной свет в пещере, руинах, на покинутом складе или под защитой местного волшебника или злого храма." },
      { from: 96, to: 96, text: "13 лет назад барон Багра стал владельцем великого сокровища —во время похода он добыл кольцо, которое маги опознали, как кольцо трех желаний. Багра не решился сразу использовать это кольцо, а хранил его для случая. И такой случай появился — 7 лет назад большой флот орков шел на город и тогда Багра призвал силу кольца. Началась буря, равной которой не помнил никто — она полностью уничтожила все корабли орков и совершенно не повредила корабли, находящиеся в гавани города. О кольце мгновенно потекли слухи и его несколько раз пытались похитить, причем украсть его попытался даже советник барона. Тогда Багра решил спрятать кольцо, что и было сделано одним из его преданных слуг. Страсти вокруг кольца начали утихать и вскоре были забыты. И вот несколько месяцев назад у барона родился долгожданный наследник. Но эта радость была омрачена тем, что наследник был очень хилый и болезненный. И тогда Багра вновь вспомнил о силе кольца. Он решил отправить за кольцом отряд, так как очень боялся за его судьбу — ведь от него теперь зависело здоровье его сына, а в последствии и его баронства — ведь слабость правителя всегда оборачивается слабостью власти, а слабость власти — потерей власти. К сожалению, официального повода для отправки большого отряда в дальний поход не было, поэтому было объявлено, что отряд идет, дабы навести порядок в одной деревеньке. Предполагается, что партия уже доказала Багру свою преданность (и желательно, чтобы доказала не один раз). Барон просит приключенцев присоединиться к походу в качестве сопровождения. Он обещает предоставить коней, кормешку, а по успешному возвращению еще и по 500 gp каждому (плюс или минус в зависимости от мира, мастера и уровней приключенцев)." },
      { from: 97, to: 97, text: "В одном из крупных городов организовывается турнир, победитель которого получает очень ценный приз на усмотрение мастера. Соответственно и противники будут не подарок." },
      { from: 98, to: 98, text: "Толпа приключенцев сидит и квасит в таверне (в любом городе, на усмотрение ДМа). В таверну входит усталый человек в запылённом плаще, садится за стол и требует кружку пива. Билл Хаббинс, менестрель, neutral good. Бывший приключенец, сейчас живёт в деревне лесорубов по дороге отсюда в город. Пришёл просить помощи, т.к. в окрестностях деревни завелось неведомое зло. Примерно неделю назад лесорубы пошли в лес, чтобы наметить новую вырубку в стороне от старой. Ночью они прибежали в деревню в полном ужасе. С тех пор по ночам там что-то жутко воет, идти туда они боятся. Ночью вблизи деревни можно услышать жуткий вой, пробирающий до костей." },
      { from: 99, to: 99, text: "Действие разворачивается в маленьком городке. Известен он в основном тем, что около ста лет назад неподалеку от его стен состоялась великая битва с армией нежити, о которой до сих пор ходят легенды. Суть в том, что зловещий Орден рвался к власти над миром, но 12 благородных героев, вооруженных магическими мечами, каждый из которых был «заточен» под владельца, сумели остановить войско мертвых, но сами пали в этой битве или скончались от ран вскоре. Гробница, в которой они похоронены, находится недалеко от города и является местной достопримечательностью. Но Орден по прежнему тянется к власти! Некоторое время тому назад молодой, но амбициозный некромант по имени Шандро удачно раскопал древний склеп, где добыл не только таинственную Корону Ебел-Забора, но и достаточно много интересных книг. В одной из них он прочитал о забытом обряде Темного Воскрешения, в ходе которого великий герой может быть поднят магом в качестве миньона. И вот в его голове созрела идея – при помощи известного этого обряда поднять древних героев битвы при Эльтерриле как послушных его воле скелетных воинов. Герои, сражавшиеся с нежитью, сами превратятся в нежить." },
      { from: 100, to: 100, text: "Пара холмовых гигантов, изгнанных из своего клана, бродят по окрестностям и терроризируют округу. Напали на деревню эльфов, убив и съев часть жителей. Далее набрели на кентавров и убили и съели нескольких из них. Объединившись против общего врага, эльфы верхом на кентаврах стали преследовать злодеев. Само собой, они будут очень рады помощи приключенцев…" },
      { from: 101, to: 101, text: "На один из прибрежных городов был совершен пиратский рейд, во время которого погиб близкий человек местного вельможи. Он нанимает приключенцев найти и покарать пиратов. Однако обычная пиратская атака была лишь прикрытием…" },
      { from: 102, to: 102, text: "Более чем 200лет назад Дварфы тайно построили шахту возле впадины для добычи редкого метала - мифрила, в той впадине находилась богатая жила этого метала. Нежелая делить их добычу между близлежащими городами, они прекратили все связи с этими городами. Но что-то пошло не так, что-то случилось страшной на дне той впадины, ни один дварф так и не вышел на поверхность. Когда контакт с шахтой был потерян, дварфы послали вооруженую партию для разведки. Группу возглавлял Хорлис Фоесмитер, могучий воин, известный своим легендарным мечем и как истребитель темных эльфов. Но ни Фоесмитер, ни его команда так и невернулась. Не желая более рисковать и быть обнаруженными местными властями, Дварфы забросили шахту и уничтожили все записи. Правда была в том, что дварфы копали все глубже, расширяя ствол шахты по мифриловой жиле. Так они докопались до великого зла…" },
      { from: 103, to: 103, text: "Приключенцы узнают о Круге Испытаний – комнате в одном из руин древнего храма. Пройдя выбранные испытания, игрок может повысить соответствующую характеристику своему персонажу (на усмотрение ДМа). Круг в какое-то очень древнее сооружение - двери могут и отсутствовать (эти двери не играют никакой роли). Комната, в которую ведут двери представляет из себя “мозайку”. Это круглая комната, в центре которой находится круглая каменная (мраморная / гранитная) плита. От этой плиты, подобно трапециям отходят семь плит. На каждой изображены давно забытые символы. Только одна плита из семи лишена символов. Оказавшись впервый раз в центре комнаты персонаж начинает чувствовать легкое покалывание и постепенно контуры комнаты размываются. После того, как двери исчезли из зрения, персонаж не может двинуться. Еще через раунд он чувствует, что снова может двигаться. Затем проясняется все вокруг. Персонаж оказывается на светящейся круглой плите. При чем ногишем, ничего с собой нет. Если он маг или клирик, он чувствует, что не может кастовать. Вокруг него семь порталов. Каждый покрыт дымкой. Над каждым порталом (его высота и ширина всегда немного больше испытуемого) табличка с двумя символами. Над одном из семи порталов - табличка с одним символом. Если прикоснуться к табличке, в мозгу возникают слова. Какие слова - определяется дверью: “Испытание Болью”, “Испытание Танцем”, “Испытание Страхом”, “Испытание Мыслью”, “Испытание Словом”, “Испытание Образом”, “Отказ”. Если персонаж входит в последную дверь, он теряет сознание и трактуется как непрошедший испытание. Если персонаж с Силой 18 и выше зашел в “испытание болью”, с Подвижностью 18 и выше в “испытание танцем” и т.д. по порядку, он просто проходит около мили по пустому коридору и выходит обратно в круглую комнату (может попытаться войти в другую дверь, но опять только если необходимый параметр менее 18). Если испытание не пройдено, персонаж очнется через 1d3 турна на той трапеции, которая ближе всего к порталу, в который он заходил. Все его шмотки при нем. Ничего нового. От всех полученных повреждений не остается никакого следа. Если п ерсонаж погиб во время испытания, на самом деле он не умирает - бросок на System Shock не нужен. Все, что произошло во время испытания забывается. Кроме этого персонаж не может пройти испытание еще раз на том-же самом Кругу (встав к Круг он испытывает такую сильную головную боль, что теряет сознание и приходит в себя через 1d6 турнов на том-же самом месте)." },
      { from: 104, to: 104, text: "Один маг неправильно прочёт заклинание и стал невидим, неслышим, неприкасаем. Он умудряется оставить послание героям с просьбой о помощи. Помочь может только…" },
      { from: 105, to: 105, text: "Магическая гильдия обладает особым магическим предметом. Это драгоценный камень, который способен создавать иллюзии в окружающем его пространстве. Эти иллюзии причиняют иллюзионарные повреждения, и когда кто- либо погибает в этих иллюзиях, то пострадавший просто теряет сознание. На партию кидаются заклинания, которые приводят к кратковременной амнезии. Затем в подземельях под магической гильдией создается иллюзия, куда и забрасываются персонажи. Еффект будет таков, что партия окажется в подземной комнате. Они не будут знать, где они и как они там очутились, но они будут помнить о своих способностях и о том, что они друзья." },
      { from: 106, to: 106, text: "Главная городская сплетня на момент появления партии в городе – это призрак единорога, который бродит по улицам лунными ночами и заглядывает в окна. Говорят, что когда-то такой бродил по улицам поселения Н., и постепенно поселение опустело, и лес поглотил его. Часть жителей умерла, часть переехала. Согласно всеобщему мнению, единорог сулит беду…" },
      { from: 107, to: 107, text: "Некоторое время назад, в водах баронства Н., был потоплен пиратский корабль варваров. Часть команды потопленного драккара спаслась и доплыла до берега. Через некоторое время они напали на ферму недалеко от побережья, ограбили ее и перебили всех мужиков. Через два дня история повторилась в другом месте. Барон выслал против них две дюжины солдат, но варвары заманили их в ловушку, где задали им жару — спаслось не более полудюжины, хотя варвары тоже потеряли несколько человек. Сейчас барон сильно озабочен появлением орочих разведчиков, объявил мобилизацию и не желает выделить даже двух человек для выслеживания этих бандитов. Но если кто-то пожелает разобраться с ними и принесет их головы, он обещал в виде награды подарить магическое кольцо. Партии необходимы кони. Иначе им просто не угнаться за варварами. Особенно если среди них есть тормоза, типа гномов и дварфов. В результате игроки объединяются с варварами против общего врага и держат оборону на далекой ферме. Однако, орков все больше и партия бежит в ближайшую деревню, где выясняется, что орков вокруг гораздо больше, чем они могли полагать. Они отправляются в столицу баронства, чтобы предупредить о нашествии, и по дороге встречают некого Хундарха, который выдает им планы вторжения, мотивируя это нежеланием развязки войны – по его словам, если нынешний полководец орков – Химрик потерпит поражение, продолжения войны не будет. С этими сведениями, партия благополучно добирается до города и встречается с заинтересованными лицами. Когда это подтверждается, город начинает готовится к осаде и отсылает гонцов за помощью. И вскоре появляется армия гоблиноидов – они берут город в осаду и начинаются тяжелые осадные деньки – регулярные штурмы, вылазки и прочее, в которых активное участие принимает и партия. Вскоре появляется помощь из соседних баронств и осажденный город начинает выводить свои войска на битву. Происходит сражение, в котором армия гоблиноидов оказывается уничтожена, а сам Химрик убит (не без помощи Хундарха). Люди празднуют победу." },
      { from: 108, to: 108, text: "Сражаются две страны. Одна из стран начинает проигрывать и обращается к злым силам за «помощью». В связи с этим резко усилилась активность Темных и Некромантских гильдий, опутавших сетью своих тайных орденов этой страны. Главной целью Темных гильдий стал артефакт – Сердце Сумерек. Этот талисман, несший в себе страшную темную силу, и принадлежавший некогда Императору Тьмы, был утерян во времена Древних войн, и лишь недавно Светлым Жрецам стало известно его местонахождение – Сердце Сумерек погребено в Храме Плачущих Теней, спрятанное от всех Черным Императором века назад. Несколько отрядов отправились к Храму с целью добыть Сердце Сумерек чтобы раз и навсегда уничтожить средоточение Зла Арландии, но никто не вернулся назад, чтобы поведать историю своих товарищей. Император отказался высылать подмогу жрецам, ему не хватало людей на фронте, и жрецы были вынуждены пытаться добыть артефакт своими силами. Агенты Темных сил так же узнали о том, что Сердце Сумерек найдено и со своей стороны предприняли попытку добыть артефакт, но тоже безрезультатно…" },
      { from: 109, to: 109, text: "Группа - пассажиры купеческого корабля \"Морская ласточка\", направляющегося из Королевства в Южные Земли. Корабль попадает в шторм и тонет, группа спасается в шлюпке и их прибивает к острову. Hа острове они находят фазенду, на которой живет некий старец-маг со своими слугами и животными, которые служат ему. Старец приветливо встречает группу, обещает им помощь в возвращении домой и просит оказать ему услугу: Живущие не другом конце острова на горе крылатые монстры похитили его волшебного помощника - кота. Hа самом деле старец - жрец злого божества. Hа острове находиться храм этого божества в котором совершаются человеческие жертвоприношения. Через три дня в этом храме - очередной праздник на который приедут паломники. Один из членов группы выбран в качестве жертвы, от остальных \"старец\" хочет избавиться, стравив их с племенем ааракокр, обитающих на другом конце острова." },
      { from: 110, to: 110, text: "Барон Минока – лорд Грейхарт решил жениться на прекрасной леди Мерилен но поскольку он барон, то и подарок жене нужен баронский. И вот решил он отправить кого-нить за кольцами в заброшенный замок алхимика Артениуса, так как узнал из секретных источников, что был этот алхимик еще и прекрасным ювелиром, и потому делал не только магические, но и великолепные по виду кольца." },
      { from: 111, to: 111, text: "Приключение начинается в маленьком городе Мидтон. Персонажи ночуют на местном постоялом дворе. Ночью все старшие сыновья в каждой семье города оказываются убиты. Приключенцев вызывают в местный храм и просят помочь выяснить, кто виноват в этом преступлении и как избежать дальнейших атак - в том числе найдя и уничтожив источник несчастья. Персонажи узнают, что мертвые тела внезапно поднялись и зашагали прочь. Кроме тех, кого видели убитым и разгуливающим в дохлом виде, исчезло несколько горожан и их семей. Преследуя ходячих покойников в течение 6-12 часов, партия углубляется в леса. Проходит день, и реальный мир становится все менее реальным, а сны - все более живыми. В своих сновидениях партия встречается с ведьмой верхом на кошмаре, с душами мертвых горожан и со злым жрецом. Они прибывают в храм (во сне, в котором остаются до конца приключения), проходят мимо статуи Шхара (которую нужно приветствовать), встречают 2 группы служителей Шхара и прерывают 1 обряд. Во время сражений, персонажи обнаруживают, что живые существа, убитые в храме, поднимаются как нежити немного погодя. В Части 2 партия поднимается на 2-й уровень храма. Приключенцы встречают множество NPC, в том числе ракшаса, юного дракона, двух диких эльфов и варвара. У этих NPC они получают предметы, необходимые, чтобы выйти на 3 -й уровень. Здесь также есть несколько комнат, которые они могут исследовать, включая кухню (с поварихой-огненным гигантом) и спальнями персонажей из Мидтона, которые добровольно вступили в храм. На верхнем уровне (Часть 3), персонажи встретят нескольких жрецов, которых могут либо убить, либо отпустить. Партия временно будет телепортирована в Гадес, где встретится с добрым волшебником и получит инструкции. После возвращения партия встретится с верховным жрецом и его любовницей и, возможно, их уничтожит. Партия “освятит” проклятый алтарь и найдет 2 выхода из алтарной комнаты в сверхпространственное измерение. Исследовав их и получив некоторые важные магшмотки, персонажи почувствуют зло, исходящее с нижних уровней храма, и отправятся туда, чтобы уничтожить его. Там они найдут прежнего верховного жреца, ставшего нежитью (wraith), он же главный жрец Шхара. Жрец потребует, чтобы партия еще раз убила того жреца, которого они запинали несколько минут назад (сейчас он вампир), пока он уязвим. Они сделают это и уйдут, прорвавшись через орду нежитей. Ослабленный храм после этого покинет данный план. Что и требовалось." },
      { from: 112, to: 112, text: "Лорд Дервик говорит, что «не далеко от нашего славного города завелась какая- то пакость. Крестьяни из одной деревни пришли с просьбой о помощи - возле их деревни, в болотах, есть древняя башня. И вот пару недель назад из башни был слышен какой-то жуткий вой и смех. С тех пор это повторяется каждую ночь, а в последние несколько дней случились еще более страшные вещи - сначала была уничтожена вся живность одного фермера, который живет ближе остальных к этой башне, а на следующее утро в таком же виде нашли мертвым и самого фермера.» Также он скажет, что «местные слишком боятся этой башни и не берутся за эту работу». Если приключенцы согласятся идти на задание, то с лорд пошлет с ними свое доверенное лицо - Лорка (капитан королевской гвардии). В случае, если приключенцы начнут протестовать против такой компании Лорк пойдет за ними следом. На самом деле настоящий Лорк давно мертв, а его место занял допльгангер по имени Арзакор." },
      { from: 113, to: 113, text: "Приключенцев ставят в известность о том, что разрозненные племена разнообразных гигантов, издавна обитавшие в горах, начали нападать на людей, разрушая деревни и унося пленных (чего они раньше никогда не делали). Гиганты даже перебили шайку разбойников Хромого Билли, с которым до того никто не мог справиться. Во всяком случае, его изуродованный труп вместе с группой прочих членов шайки не так давно нашли прямо на дороге. .В чем причина - по одним слухам, у гигантов появился новый лидер, по другим, в деле замешаны Drow, которые были виновны в прошлом обострении войны. В действительности все гораздо сложнее. Гиганты абсолютно непричастны ко всем преступлениям. Реальный виновник – злокозненный маг-иллюзионист Сид Марра, каковой в поисках высшей власти заключил союз с неким демоном высокого ранга, - Повелителем Козлов (во всех смыслах) Нъярлатотепом, черпающим свою силу из человеческих страданий и раздора, который подарил ему магическое кольцо и потребовал в награду, чтобы Марра развязал войну между гигантами и людьми." },
      { from: 114, to: 114, text: "Некогда живший в городе маг проводил непонятные эксперименты с животными. Точнее с крысами. Суть своих экспериментов он скрывал. Занимался он этим не один год и однажды что-то пошло не так и его ученик, без разрешения вошедший в его дом нашел учителя мертвым. Он был загрызен и обглодан, кругом было множество следов, напоминающих следы больших кошек. Также несколько клеток, где он содержал своих подопытных были открыты и пусты. Также стоит отметить, что все его книги были злобно погрызены крысами. Кенар (этот самый маг) хотел сделать их крыс верных слуг своих (солдат, рабочих, шпионов и так далее). Ему даже удалось наделить их разумом. Но это его погубило — однажды главный (и самый умный) крыс, которого Кенар любовно называл “Король” вылез из клетки и перегрыз горло мирно спящему Кенару. Затем он освободил некоторых крыс — мутантов, кои ему подчинились. Они прожили в доме мага несколько дней, затем, когда еда начала подходить к концу (книги магии, остатки мага и так далее) Король и его “свита” покинули славное местечко и поселились в канализации. История была бы забыта, если бы примерно через год после этого случая местный бродяжка не нашел в канализации обглоданный труп. Тогда эту историю не вспомнили, но примерно через два месяца другой бродяга уверял, что на него напали толпы гиганских крыс и спасся он только чудом. По его словам крысы были размером чуть ли не с медведя (special for DM: Пить надо меньше :-). Еще месяц прошел относительно спокойно и вновь было найдено обглоданное тело. Вот тогда люди всполошились и заставили совет предпринять хоть какие-то действия." },
      { from: 115, to: 115, text: "Лорд Каседахк Фалаш III известен в городе Грогринльд как богатый плэйбой, славящийся своими дикими оргиями и невероятными пирами. Он любит устраивать щедрые пиры, не заботясь о деньгах, чтобы развлечь, и часто потрясти своих гостей. Вечеринка обычно устраивается на определенную тему. На сей раз, тема - авантюристы. Лорд Фалаш хочет устроить очередной пир и приглашает настоящих, живых авантюристов. Конечно, он знает, что они могут быть опасны и непредсказуемы, поэтому он хочет относительно молодых и безопасных авантюристов. Чтобы застраховаться от выходок искателей приключений, он нанял трех довольно сильных охранников - братьев Клод, широко известных как своими пустыми головами и широкими плечами. Хурак, старший, немного более интеллектуален в отличие от двух своих братьев (так как доказан факт, что он может считать обоих своими братьями), и он их лидер. Дисак и Трул предпочитают, чтобы за них думал Хурак. Братья остаются за кулисами, и появятся только если Лорду Фалашу будет угрожать опасность. Естественно, Фалаш хочет, чтобы его пирушка прошла на славу. Чтобы все прошло наверняка, он с помощью Котоса Мудрого, местного шарлатана, составил сложный план. Котос будет использовать свои способности чтобы \"поохотиться\" на участников пирушки. Фалаш в этот момент планирует обратиться к своим гостям (авантюристам) за помощью, с просьбой \"спасти нас, избавив от этого ужасного проклятья\". Чтобы держать своих гостей \"пленниками\" в течение этого фарса, Фалаш планирует с помощью братьев Клод, заблокировать проход в замок - единственный мост, переброшенный через ущелье, который ведет к Поместью Ковертон. Также, с помощью иллюзорной магии, Котос Мудрый убедит гостей, что начался сильный шторм, который будет бушевать до утра. Конечно, все пошло, как надо. Лорд Фалаш не знает, что его слуга Паша подслушал разговор с Котосом, и узнал все об их планах. Он продал эту информацию в местную гильдию воров, которая в свою очередь передала её Ричмонду, путешествующему магу / вору. Ричмонд решает использовать пирушку в своих целях. Три месяца назад, он выиграл в покер странную коробку. Открыв её, он был атакован странным зеленым туманом, который исторгся изнутри. Он сумел победить туман, загнав его с помощью магии обратно в коробку. С тех пор Ричмонд экспериментировал с выпусканием тумана на ничего не подозревающих путников. К его восхищению, туман убивал его жертвы, и Ричмонду оставалось только раздеть тела. Он быстро стал довольно преуспевающим разбойником, позволяя туману делать всю грязную работу за него. Туман, получавший регулярную пищу, скоро приручился, и больше не пытался уничтожить своего владельца. Туман оставляет после себя мощный аромат корицы, который можно учуять на месте его физического проявления в течение 20 мин. План Ричмонда - выпустить туман в особняке Фалаша, после того, как Котос Мудрый начнет свой иллюзорный шторм. Гости, и в том числе авантюристы, умрут. Ричмонд надеется, что туман убьет гостей одного за другим, оставляя золото и сокровища, и Ричмонду останется только собрать все это." },
      { from: 116, to: 116, text: "Игроки начинают приключение, не входя в подземелье, а только-только выйдя из него. Поход внутрь был не очень удачен, - среди трофеев лишь некоторое количество магических предметов, явно имеющих отношение к темному культу, некромагам, демонологам и тп. В дополнение один из героев серьезно пострадал в ходе операции и большую половину времени модуля будет находиться в состоянии болезни - проклятия. Для того чтобы добыть денег на магическое лечение раненого товарища, героям приходится продать на черном рынке свои трофеи, которые мгновенно становятся пешками в местных интригах. И вот по обвинению в демонологии и осквернении могил обвинен некий человек, а главными изобличающими его уликами (хотя осквернение произошло раньше появления РС в городе) являются те самые «предметы культа». Буде РС сумеют правильно решить эту проблему и распутать клубок, они получают покровительство влиятельной гильдии наемников, представителя которой им удается спасти от костра." },
      { from: 117, to: 117, text: "Племя гурам (подвид лесных гномов) было изгнано со своего прежнего места кобальтами, которые, терпя постоянные поражения в борьбе с ними, заручились поддержкой двух троллей и с их помощью заставили гурам убраться. (Гурам было просто нечего противопоставить таким монстрам). Они переселились поближе к людскому поселению. После их начал поедать очень сильный монстр. Не зная людей достаточно хорошо, гурам решили, что появление монстра также связано с людьми и решили, что на этот раз они будут бороться до конца — или они, или люди. На самом деле монстр не связан с людьми и жрёт всех подряд." },
      { from: 118, to: 118, text: "Героям надо попасть в одну очень глухую деревню, находящуюся высоко в горах или в джунглях. Чтобы туда попасть, героям придётся очень долго и тяжело пробираться, встречая большое количество опасностей по пути…" },
      { from: 119, to: 119, text: "Один из магов воровал гоблинов и делал и, сделав их своими слугами, ставил на них эксперименты, после который гоблины стали передвигаться со скоростью гепарда, умело фехтовать кинжалами, а их кожа стала каменная и почти непробиваема оружием. Единственная слабость кожи – сильная чувствительность к огню. Что задумал маг? Зачем ему понадобились сделать собственную армию усиленных гоблинов?" },
      { from: 120, to: 120, text: "Раньше орки были весьма дезорганизованы, но с тех пор как прибыл Глазар все изменилось. Орки стали беспрекословно подчиняться Глазару, а тот в свою очередь сплотил их и создал не большую армию под своим началом. Он позволил оркам держать при себе небольшое количество сокровищ, а самым сильным из них даже выдал волшебное оружие. Орки счастливы и никогда не повернутся от своего хозяина. Глазар - молодой зеленый дракон он поселился в горе, там же когда-то была скрытая могила. В ней он обнаружил не большую чашу заполненную бусинками, (Firebeds) эти бусинки волшебные, когда их кидаешь они взрываются как FireBall. Эти бусинки он выдал оркам, для устрашающего оружия. Логово Глазара находится к северу от города примерно 2 мили придётся топать через лес." },
      { from: 121, to: 121, text: "Приключенцы набредают на пещеру, в глубине которой в воздухе висит драгоценный камень и светится зелёным светом. Это камень жадности. Все, кто к нему приближаются, считают, что их коллеги хотят их ограбить и при провалившихся спасбросках атакуют своих же союзников. Сам камень охраняют Огни Жадности. Смогут ли игроки достать этот камень?" },
      { from: 122, to: 122, text: "Гоблины, руководимые человеком-вором высокого уровня, грабят корованы и близлежащие населённые пункты. Натренированные вором, они на порядок опаснее обычных гоблинов. Делают хитрые засады и тактически сражаются. Противник сложный." },
      { from: 123, to: 123, text: "Один злой лорд желая огромной власти – присягнул всемогущему дракону на верность в обмен на то, что его сделают по силе равным самому дракону. Лукавый дракон выполнил просьбу лорда, но сделал его при этом нежитью. Этот лорд смог захватить столицу, сделав ее городом мёртвых. Теперь он хочет завоёвывать и дальше территории. Победить его можно только при помощи магического меча…" },
      { from: 124, to: 124, text: "В поисках древнего храма в лесу, приключенцы набредают на миловидную эльфийскую деревушку. Им обещают помочь в поисках. Но эльфы только на первый взгляд выглядят мирными грин-писовцами. На деле они оборотни, охотящиеся по ночам на всех подряд и не прочь полакомиться героями…" },
      { from: 125, to: 125, text: "Приключенцев просят сопроводить караван. Караванщик оказывается наёмником на службе у злого колдуна, который заманивает благодаря караванщику авантюристов и убивает, делая из них подчинённую нежить, но с воинскими навыками, которые были у героев при жизни." },
      { from: 126, to: 126, text: "В городе был убит ювелир и похищен кольцо с драгоценным камнем, которое делали специально для лорда Ланстера. Возмущённый лорд нанимает авантюристов вернуть кольцо. Однако, по возвращении пропажи, оказывается, что кольцо заколдовали и надев его, лорд Ланстер…" },
      { from: 127, to: 127, text: "Один крокодил съел вместе с магом волшебный предмет и теперь…" },
      { from: 128, to: 128, text: "Группа появляется в библиотеке, они помнят, кто они такие, но все что связано с тем, как они сюда попали они не помнят. Читая различные книги и записки, они начинают понимать, как они тут очутились, и что нужно сделать чтобы выбраться. Им недоступна только одна дверь – она заперта изнутри. Походив по замку, они находят топор, зеркало и ключ. После того, как они снимут зеркало за ним окажется отверстие в стене. Выйдя из замка, они находят подсобку, которую открывают ключом, там стоит лопата. На кладбище они выкапывают могилу Катрины Ителл, отрубают ей руку, которую потом берут с собой. После этого они опять заходят в комнату с зеркалом, и кладут руку Катрины в отверстие. Открывается дверь в стене. Когда партия заходит внутрь, они чувствуют сонливость, падают на пол, и уже на грани потери сознания, понимают, что это какой - то склеп. Они просыпаются в лабиринте в виде зомби, у них есть около 27 ходов, чтобы выбраться из него, иначе они расыпятся (Через каждые 7-8 ходов у них что-то отваливается). Пройдя лабиринти нажав на рычаг они просыпаются опять в бибилиотеке. Теперь им доступна дверь в которую они не могли попасть раньше. Это колокольня. Там на крюк от колокола они вешают зеркало. После этого они возвращаются в главный зал и переносятся в реальный мир. Они вспоминают, что они подрядились на работу к местному магу, как испытатели нового заклинания, способного переносить сознание в другие миры." },
      { from: 129, to: 129, text: "Мок Шеб, тролль, переехал со своей группой рейдеров в затерянную и забытую Гробницу. Оттуда он предпринимает нападения на караваны, проходящие поблизости, и даже, при случае, на ближайшие маленькие деревушки в нескольких милях отсюда. Гробница в своё время была очень популярна у паломников, но с захватом этой территории орками, гробница на столетия была всеми заброшена и забыта. Какие тайны она может скрывать?" },
      { from: 130, to: 130, text: "Приключенцы попадают на остров, который в реальности оказывается живым существом, пожирающим своих посетителей. Удастся ли героям выжить и выбраться из острова?" },
      { from: 131, to: 131, text: "Несколько сотен лет назад юная волшебница Солана обнаружила старую рукопись в библиотеке своего учителя, чье имя стерлось в веках. Забыв, что с магическими рукописями надо поступать осторожно, она произнесла заклинание вслух. К сожалению, спелл не требовал жестов, и заклятье тотчас сработало, окружив башню густым туманом, а всех ее обитателей в крепкий сон. Более того, со временем заклинание не только не растеряло силу, но захватило под свое воздействие соседний город. Большинство жителей уснули крепким сном, а те, кто сопротивлялся магии дольше, потеряли большую часть своих жизненных сил и превратились в тени тех, кем они были. Множество героев бывало в тех землях, но никто еще не смог пробудить башню ото сна." },
      { from: 132, to: 132, text: "Этот модуль про злое божество друидов Малара, его друида, и прирученного Медведьсову (Owlbear). Живя в закрытой роще, которую охраняют заклинания друидов, они используют зверей для жестоких убийств. Два года назад, друид по имени Джоррен заметил, что его любимая часть леса понемногу исчезает под топорами людей. Они игнорировали его просьбы остановиться, и его предложения относительно того, как они смогут получить древесину, не причиняя такого огромного вреда лесу. Возмущенный, он обратился к богу. Малар в отличие от многих других богов природы, склонен к насилию и злу, понемногу начал нагнетать друиде гнев и подталкивать его к мести. Однажды, глубоко в чаще леса, Джоррен нашел яйцо Медведьсовы, из которого вылупился детеныш. Со временем, друид приручил птенца, и тот стал слушаться его. Через некоторое время птенец вырос, и друид стал посылать медведьсову для нападений на лесорубов, охотников, и отдаленные фермы. Иногда он усиливает его своими долгодлящимися заклинаниями, или присоединяется к нему, вмести со своими рейнджерами – Полуорками. Они сеют страх и ужас, и никогда не оставляют следов." },
      { from: 133, to: 133, text: "Золотой дракон, принимая обличие книжника, отправляет авантюристов в пещеру под предлогом достать ценную ему вещь, где их испытывает. Если приключенцы выходят живыми, то он их награждает." },
      { from: 134, to: 134, text: "Один волшебник проклял деревню и теперь каждую полночь на кладбище образуется ядовитый зелёный туман. Каждый игрок который попал на кладбище в полночь должен делать спас бросок на выносливость 18. Если спас не выкинут, персонаж становится крайне злым и должен повторять спас бросок каждый раз при наступлении полуночи. Если же персонаж не выкидывает спас 3 раза подряд, он умирает. Но, если персонаж выкидывает удачный спас бросок и не находится под воздействием тумана опять (смотри далее), то он выздоравливает в течении недели." },
      { from: 135, to: 135, text: "Несцент, инфернальное зло, использовал тело воина Тирнгаэля, чтобы убрать других военачальников, используя неожиданность и специальное кольцо. Некоторые думают, что при помощи него он получил свою мощь и силу. Паладины «Гарадон» обнаружили истинную природу демона, после чего решили устроить ловушку в цитадели. Там они убили оболочку Тирнгаэля и заманили в ловушку Несцента, посадив в антимагическое поле(antimagic field). Они переделали крепость в могилу, и защитили ее при помощи Мепфитов (Mephits)." },
      { from: 136, to: 136, text: "Отряд орков, грабя всё подряд, разграбил склеп, где пробудился древний злой колдун-вервольф, который оказался ликантропом. Он получил шанс собрать свою собственную стаю. Он заразил 9 орков ликантропией, убил двоих, остальные 11 бежали в леса и их больше никто не видел…" },
      { from: 137, to: 137, text: "Герои забредают в город, который внегласно контролируется изгнанным из своего подземного города иллитидом (Mind Flayer). Этот город он планирует сделать плацдармом для возрождения иллитидской империи." },
      { from: 138, to: 138, text: "Герои по одной из причин на усмотрение ДМа попадают в заброшенный особняк. Дом поглотила петля времени, из-за чего персонажи то и дело оказываются в разные периоды жизни обитателей дома. Причем выйти они не могут, пока не разберутся с проблемой, либо не погибнут, либо сойдут с ума (что тоже возможно). Причем то что РС скачут во времени аки зайцы не все цветочки, сам дом является приличным лабиринтом – у последнего хозяина даже был случай, когда нашли мертвого охранника, заплутавшего среди комнат и погибшего от голода." },
      { from: 139, to: 139, text: "Героев подряжают вернуть древний всевидящий шар, находящийся в башне местного мага и принадлежащий по праву роду нанимателя, но украденный потомками мага. Маг очень сильный, но пошли слухи об его отсутствии и поэтому наниматель рискнул нанять героев. Параллельно с этим, еще один маг -конкурент тоже попытает счастье забрать реликвию себе и обогнать приключенцев. Всё бы хорошо, но башня полна ловушек и, к тому же, сам маг вернулся как раз во время нахождения чужаков на его территории." },
      { from: 140, to: 140, text: "Сумасшедший друид пытается изгнать жителей соседнего с лесом городка, чтобы они не «истощали» лес. Жители отказались и друид начал собирать армию из враждебных растительных существ. Однако сам был убит одним из них и теперь монстры населяют лес и терроризируют жителей злосчастного городка. Жители просят помощи героев избавить их от монстров." },
      { from: 141, to: 141, text: "Давнее поле битвы теперь населено духами неупокоенных воинов, которые отгоняют всех авантюристов, пришедших забрать ценные вещи падших воинов…" },
      { from: 142, to: 142, text: "Один злой тифлинг нашел нашел и изучил древний друидский ритуал по превращению людей в животных. Таким образом при помощи сообщников, он превратил в животных всех жителей деревни и подчинил их себе, а тех, кто сопротивлялся – убил." },
      { from: 143, to: 143, text: "Один старый некромант с целью не умереть – посвятил остаток своей жизни на сбор знаний о том, как стать личем и жить вечно. Для достижения своей цели он пойдёт на всё…" },
      { from: 144, to: 144, text: "На месте, где стоит городок, было поселение хобгоблинов. После смерти их сильнейшего предводителя, вскоре хобгоблины были разбиты другими монстрами. Спустя сотни лет, после удара молнии в древний могильник, предводитель хобгоблинов восстал из мёртвых и жаждет мести…" },
      { from: 145, to: 145, text: "Глава разбитой банды разбойников решил отомстить обидчикам и с помощью найденного артефакта поглощающего воду, иссушает всю округу. Его необходимо срочно остановить!" },
      { from: 146, to: 146, text: "На поиски осколка древнего кристалла, дающего владельцу огромную мощь, отправили группу авантюристов под предводительством волшебника Ангрима. После тяжелых препятствий им удалось добыть осколок, но маг под влиянием осколка – убил оставшихся в живых компаньонов и скрылся, готовя что-то опасное для округи. На что способен этот осколок? Это он вынудил Ангрима убить собственных сопартийцев?" },
      { from: 147, to: 147, text: "Приключенцам поручили поймать пиратов корабля Мрачный Дрейк. Однако, легко ли это будет сделать, если вокруг полно шпионов, работающих на этих пиратов?" },
      { from: 148, to: 148, text: "Один злодей ворует священный гоблинский артефакт, обладающий волшебными свойствами, и натравливает гоблинов на своих врагов, говоря, что это артефакт выкрали именно они." },
      { from: 149, to: 149, text: "Дварф бронник нанимает героев, чтобы они вернули ему шкуру зелёного дракона, украденную из его. разграбленного каравана. Шкуру он намеревается пустить на отличный чешуйчатый доспех." },
    ],
  },
];
